WITH parsed AS (SELECT id, customer_id, created_at, ship_to, attributes, ARRAY_MAX(TRANSFORM(items, li -> li.price)) AS max_item_price, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10, TRANSFORM(items, li -> li.product_id) AS product_ids, COALESCE(attributes['utm_source'], 'none') AS utm_source_or_default, TRANSFORM(FILTER(items, li -> li.promo IS NOT NULL), li -> STRUCT(li.product_id AS pid, ROUND(li.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts WHERE TO_DATE(created_at) < '2024-11-04') SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, DATE_TRUNC('DAY', created_at) AS activity_day, MIN(created_at) AS first_seen, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, ROUND(AVG(max_item_price), 2) AS avg_max_item_price_2, APPROX_PERCENTILE(max_item_price, ARRAY(0.25, 0.5, 0.75)) AS max_item_price_quartiles, GROUPING_ID() AS gid FROM parsed GROUP BY CUBE (DATE_TRUNC('HOUR', created_at), DATE_TRUNC('DAY', created_at)) ORDER BY hour_window DESC;
